int a = 1, b = 2, c = 3;
rotate3(&a, &b, &c);
CHECK_EQ(a, 2);
CHECK_EQ(b, 3);
CHECK_EQ(c, 1);

int a = -1, b = -2, c = -3;
rotate3(&a, &b, &c);
CHECK_EQ(a, -2);
CHECK_EQ(b, -3);
CHECK_EQ(c, -1);

int a = 4, b = 4, c = 4;
rotate3(&a, &b, &c);
CHECK_EQ(a, 4);
CHECK_EQ(b, 4);
CHECK_EQ(c, 4);
